(function () {
  const visible = (el) => {
    const style = window.getComputedStyle(el);
    const rect = el.getBoundingClientRect();
    return style.visibility !== 'hidden' && style.display !== 'none' && rect.width > 0 && rect.height > 0;
  };

  const cssEscape = (value) => {
    if (window.CSS && typeof window.CSS.escape === 'function') return window.CSS.escape(value);
    return String(value).replace(/["\\#.:,[\]>+~*'=()]/g, '\\$&');
  };

  const uniqueSelector = (candidate) => {
    try {
      return document.querySelectorAll(candidate).length === 1 ? candidate : null;
    } catch {
      return null;
    }
  };

  const selectorFor = (el) => {
    const tag = el.tagName.toLowerCase();
    if (el.id) return `#${cssEscape(el.id)}`;
    const testId = el.getAttribute('data-testid') || el.getAttribute('data-test');
    if (testId) {
      const candidate = `${tag}[data-testid="${cssEscape(testId)}"]`;
      const unique = uniqueSelector(candidate);
      if (unique) return unique;
    }
    const name = el.getAttribute('name');
    if (name) {
      const candidate = `${tag}[name="${cssEscape(name)}"]`;
      const unique = uniqueSelector(candidate);
      if (unique) return unique;
    }

    const parts = [];
    let node = el;
    while (node && node.nodeType === Node.ELEMENT_NODE && node !== document.documentElement) {
      const nodeTag = node.tagName.toLowerCase();
      let position = 1;
      let sibling = node;
      while ((sibling = sibling.previousElementSibling)) {
        if (sibling.tagName.toLowerCase() === nodeTag) position += 1;
      }
      parts.unshift(`${nodeTag}:nth-of-type(${position})`);
      const candidate = parts.join(' > ');
      if (uniqueSelector(candidate)) return candidate;
      node = node.parentElement;
    }
    return parts.join(' > ') || tag;
  };

  const textPreview = (el) => (el.innerText || el.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 80);

  const elementDetails = (el) => {
    const attrs = {};
    ['id', 'class', 'name', 'type', 'role', 'aria-label', 'aria-labelledby', 'aria-describedby', 'placeholder', 'href', 'value'].forEach((name) => {
      const value = el.getAttribute(name);
      if (value) attrs[name] = value.slice(0, 160);
    });
    const rect = el.getBoundingClientRect();
    return {
      tag: el.tagName.toLowerCase(),
      attributes: attrs,
      text: textPreview(el),
      bounds: {
        width: Math.round(rect.width),
        height: Math.round(rect.height),
        x: Math.round(rect.x),
        y: Math.round(rect.y),
      },
    };
  };

  const elementSummary = (el) => {
    const details = elementDetails(el);
    const attrs = details.attributes;
    const parts = [`<${details.tag}`];
    ['id', 'name', 'type', 'role', 'aria-label', 'placeholder'].forEach((name) => {
      if (attrs[name]) parts.push(`${name}="${attrs[name]}"`);
    });
    return `${parts.join(' ')}>`;
  };

  const pushNode = (arr, el, index, summary) => {
    arr.push({
      target: [selectorFor(el)],
      html: (el.outerHTML || '').slice(0, 240),
      element: elementDetails(el),
      elementSummary: elementSummary(el),
      failureSummary: summary,
    });
  };

  const rules = () => {
    const violations = [];

    const langNodes = [];
    if (!(document.documentElement.getAttribute('lang') || '').trim()) {
      pushNode(langNodes, document.documentElement, 0, 'Document language is missing.');
      violations.push({
        id: 'html-lang',
        help: 'Document must declare a language',
        impact: 'serious',
        description: 'The page does not declare a language on the html element.',
        nodes: langNodes,
      });
    }

    const imageNodes = [];
    document.querySelectorAll('img').forEach((img, index) => {
      if (visible(img) && !img.hasAttribute('alt')) {
        pushNode(imageNodes, img, index, 'Visible image has no alt text.');
      }
    });
    if (imageNodes.length) {
      violations.push({
        id: 'image-alt',
        help: 'Images must have alternative text',
        impact: 'moderate',
        description: 'Visible images should have alt text or be marked decorative.',
        nodes: imageNodes,
      });
    }

    const labelNodes = [];
    document.querySelectorAll('input, textarea, select').forEach((el, index) => {
      const type = (el.getAttribute('type') || '').toLowerCase();
      if (!visible(el) || ['hidden', 'submit', 'button'].includes(type)) return;
      const hasLabel = !!el.labels?.length || !!el.getAttribute('aria-label') || !!el.getAttribute('aria-labelledby');
      if (!hasLabel) {
        pushNode(labelNodes, el, index, 'Form control does not have an associated label.');
      }
    });
    if (labelNodes.length) {
      violations.push({
        id: 'label',
        help: 'Form elements must have labels',
        impact: 'serious',
        description: 'Visible form controls should expose an accessible label.',
        nodes: labelNodes,
      });
    }

    const nameNodes = [];
    document.querySelectorAll('button, [role="button"], a[href]').forEach((el, index) => {
      const name = (el.innerText || el.textContent || el.getAttribute('aria-label') || '').trim();
      if (visible(el) && !name) {
        pushNode(nameNodes, el, index, 'Interactive control has no accessible name.');
      }
    });
    if (nameNodes.length) {
      violations.push({
        id: 'button-name',
        help: 'Interactive controls must have accessible names',
        impact: 'serious',
        description: 'Buttons and links should expose a text label or accessible name.',
        nodes: nameNodes,
      });
    }

    const duplicateNodes = [];
    const ids = new Map();
    document.querySelectorAll('[id]').forEach((el) => ids.set(el.id, (ids.get(el.id) || 0) + 1));
    document.querySelectorAll('[id]').forEach((el, index) => {
      if ((ids.get(el.id) || 0) > 1) {
        pushNode(duplicateNodes, el, index, `Duplicate id "${el.id}" detected.`);
      }
    });
    if (duplicateNodes.length) {
      violations.push({
        id: 'duplicate-id',
        help: 'IDs must be unique',
        impact: 'moderate',
        description: 'Duplicate IDs can break labels and assistive technology references.',
        nodes: duplicateNodes,
      });
    }

    const headingNodes = [];
    let lastLevel = 0;
    document.querySelectorAll('h1, h2, h3, h4, h5, h6').forEach((el, index) => {
      const level = Number(el.tagName.slice(1));
      if (lastLevel && level > lastLevel + 1) {
        pushNode(headingNodes, el, index, `Heading order jumps from h${lastLevel} to h${level}.`);
      }
      lastLevel = level;
    });
    if (headingNodes.length) {
      violations.push({
        id: 'heading-order',
        help: 'Headings should follow a logical order',
        impact: 'moderate',
        description: 'Heading levels should not skip intermediary levels.',
        nodes: headingNodes,
      });
    }

    const titleNodes = [];
    if (!(document.title || '').trim()) {
      pushNode(titleNodes, document.documentElement, 0, 'Document title is missing.');
      violations.push({
        id: 'document-title',
        help: 'Documents must have a title',
        impact: 'serious',
        description: 'The page does not expose a document title.',
        nodes: titleNodes,
      });
    }

    const iframeNodes = [];
    document.querySelectorAll('iframe').forEach((el, index) => {
      if (visible(el) && !(el.getAttribute('title') || '').trim()) {
        pushNode(iframeNodes, el, index, 'Iframe is missing a descriptive title.');
      }
    });
    if (iframeNodes.length) {
      violations.push({
        id: 'frame-title',
        help: 'Iframes should have descriptive titles',
        impact: 'moderate',
        description: 'Visible embedded frames should expose a title so assistive technology can describe them.',
        nodes: iframeNodes,
      });
    }

    const formErrorNodes = [];
    document.querySelectorAll('input[aria-invalid="true"], textarea[aria-invalid="true"], select[aria-invalid="true"]').forEach((el, index) => {
      const describedBy = (el.getAttribute('aria-describedby') || '').trim();
      if (!describedBy) {
        pushNode(formErrorNodes, el, index, 'Invalid field is not associated with supporting error text.');
      }
    });
    if (formErrorNodes.length) {
      violations.push({
        id: 'aria-invalid-feedback',
        help: 'Invalid fields should reference visible error feedback',
        impact: 'moderate',
        description: 'Inputs flagged as invalid should reference supporting feedback with aria-describedby.',
        nodes: formErrorNodes,
      });
    }

    const ariaNodes = [];
    document.querySelectorAll('[aria-hidden], [aria-expanded], [aria-controls], [aria-labelledby], [aria-describedby]').forEach((el, index) => {
      if (!visible(el)) return;
      if (el.hasAttribute('aria-controls')) {
        const targetId = el.getAttribute('aria-controls');
        if (targetId && !document.getElementById(targetId)) {
          pushNode(ariaNodes, el, index, `aria-controls references missing element "${targetId}".`);
        }
      }
      if (el.hasAttribute('aria-labelledby')) {
        const ids = (el.getAttribute('aria-labelledby') || '').split(/\s+/).filter(Boolean);
        if (ids.some((id) => !document.getElementById(id))) {
          pushNode(ariaNodes, el, index, 'aria-labelledby references a missing element.');
        }
      }
    });
    if (ariaNodes.length) {
      violations.push({
        id: 'aria-valid',
        help: 'ARIA relationships must point to existing elements',
        impact: 'moderate',
        description: 'ARIA reference attributes should point to existing elements in the DOM.',
        nodes: ariaNodes,
      });
    }

    return violations;
  };

  window.__launchGuardA11y = {
    selectorFor,
    elementDetails,
    elementSummary,
  };

  window.axe = {
    run: async function () {
      return { violations: rules() };
    }
  };
})();
